mapper.select:
SELECT tenant_id,outbox_id,status,attempt_count,locked_by,
                   correlation_id,lock_version
            FROM outbox_event
            WHERE contract_ref=#{contractRef} AND contract_version=#{contractVersion} AND aggregate_type=#{aggregateType}
              AND attempt_count<=#{maxAttempts}
              AND ((status='PENDING' AND next_attempt_at<=#{now})
                OR (status='PUBLISHING' AND locked_at<=#{leaseCutoff}))
            ORDER BY CASE WHEN status='PENDING' THEN next_attempt_at ELSE locked_at END,
                     tenant_id,outbox_id
            LIMIT #{limit}

mapper.update:
UPDATE outbox_event SET status='PUBLISHING',locked_by=#{token},locked_at=#{now},
                    lock_version=lock_version+1,updated_at=#{now},updated_by_type='SERVICE',updated_by_id=NULL
                WHERE tenant_id=#{candidateTenantId} AND outbox_id=#{candidateOutboxId} AND status='PENDING' AND attempt_count=#{maxAttempts}
                  AND lock_version=#{candidateLockVersion} AND next_attempt_at<=#{now}

UPDATE outbox_event SET locked_by=#{token},locked_at=#{now},lock_version=lock_version+1,
                    updated_at=#{now},updated_by_type='SERVICE',updated_by_id=NULL
                WHERE tenant_id=#{candidateTenantId} AND outbox_id=#{candidateOutboxId} AND status='PUBLISHING' AND attempt_count=#{maxAttempts}
                  AND locked_by=#{candidateLockedBy} AND lock_version=#{candidateLockVersion} AND locked_at<=#{leaseCutoff}

UPDATE outbox_event SET status='PUBLISHED',locked_by=NULL,locked_at=NULL,
                last_error_code=NULL,broker_confirmed_at=#{now},lock_version=lock_version+1,
                updated_at=#{now},updated_by_type='SERVICE',updated_by_id=NULL
            WHERE tenant_id=#{rowTenantId} AND outbox_id=#{rowOutboxId} AND status='PUBLISHING' AND attempt_count=#{rowAttemptCount}
              AND locked_by=#{rowClaimToken} AND lock_version=#{rowLockVersion} AND locked_at>#{leaseCutoff}

UPDATE outbox_event SET status='PENDING',next_attempt_at=#{nextAttemptAt},locked_by=NULL,locked_at=NULL,
                last_error_code=#{errorCode},broker_confirmed_at=NULL,lock_version=lock_version+1,
                updated_at=#{now},updated_by_type='SERVICE',updated_by_id=NULL
            WHERE tenant_id=#{rowTenantId} AND outbox_id=#{rowOutboxId} AND status='PUBLISHING' AND attempt_count=#{rowAttemptCount}
              AND locked_by=#{rowClaimToken} AND lock_version=#{rowLockVersion} AND locked_at>#{leaseCutoff}

UPDATE outbox_event SET status='RECOVERY_REQUIRED',next_attempt_at=#{now},locked_by=NULL,
                locked_at=NULL,last_error_code=#{code},broker_confirmed_at=NULL,lock_version=lock_version+1,
                updated_at=#{now},updated_by_type='SERVICE',updated_by_id=NULL
            WHERE tenant_id=#{rowTenantId} AND outbox_id=#{rowOutboxId} AND status='PUBLISHING' AND attempt_count=#{rowAttemptCount}
              AND locked_by=#{rowClaimToken} AND lock_version=#{rowLockVersion} AND locked_at>#{leaseCutoff}
